  static async createWaitlistEntry(input: {
    customerId: number;
    customerUsername?: string | null;
    productId: number;
    productName: string;
  }): Promise<{ id: string; success: boolean }> {
    const db = getFirestore();
    const docId = `waitlist_${input.productId}_${input.customerId}`;
    await db.collection("waitlist").doc(docId).set({
      id: docId,
      customer_id: input.customerId,
      customer_username: input.customerUsername || null,
      product_id: input.productId,
      product_name: input.productName,
      status: "WAITING",
      created_at: new Date().toISOString(),
    });
    return { id: docId, success: true };
  }
